import java.util.*;
import static java.lang.Math.ceil;

public class PerfGateCi {
    public static Map<String, Object> perfGateCi(List<Double> times) {
        if (times == null || times.isEmpty()) {
            return Map.of("passed", false, "error", "no data");
        }
        List<Double> sorted = times.stream().sorted().toList();
        double p95 = percentile(sorted, 95);
        double p99 = percentile(sorted, 99);
        double max = sorted.get(sorted.size() - 1);
        boolean passed = p95 < 500 && p99 < 1000 && max < 3000;
        return Map.of(
            "p95", p95,
            "p99", p99,
            "max", max,
            "passed", passed
        );
    }

    private static double percentile(List<Double> sorted, double p) {
        int index = (int) ceil(p / 100.0 * sorted.size()) - 1;
        return sorted.get(Math.max(0, index));
    }
}

